def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = DAILY_SALARY * 0.22
        if hp <= 2 or no_water_days >= 2:
            safe_bid = DAILY_SALARY * 0.55
        return float(min(budget, safe_bid))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units <= 1.05:
        scarcity = 3
    elif units <= 1.6:
        scarcity = 2
    elif units <= 2.2:
        scarcity = 1

    prev_bids = []
    stressed_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= 500:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            stressed_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if urgency >= 5:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 4.0)
    elif scarcity >= 3:
        if urgency >= 2:
            bid = max(DAILY_SALARY * 0.88, highest_prev + 3.0)
        else:
            bid = max(DAILY_SALARY * 0.62, avg_prev * 0.72 + 2.0)
    elif scarcity == 2:
        bid = DAILY_SALARY * 0.46 + rich_opp * 3.0 + stressed_opp * 2.0
        if highest_prev > 0:
            bid = max(bid, min(highest_prev * 0.58 + 1.5, DAILY_SALARY * 0.78))
        if urgency >= 2:
            bid = max(bid, DAILY_SALARY * 0.68)
    elif scarcity == 1:
        bid = DAILY_SALARY * 0.30 + rich_opp * 2.0
        if highest_prev > DAILY_SALARY * 0.9:
            bid = min(bid, DAILY_SALARY * 0.28)
        elif highest_prev > 0:
            bid = max(bid, min(highest_prev * 0.33, DAILY_SALARY * 0.42))
        if urgency >= 2:
            bid = max(bid, DAILY_SALARY * 0.55)
    else:
        bid = DAILY_SALARY * 0.18
        if urgency >= 2:
            bid = DAILY_SALARY * 0.42
        if highest_prev > DAILY_SALARY * 1.2:
            bid = min(bid, DAILY_SALARY * 0.16)

    if day >= 8 and hp >= 6 and urgency == 0:
        bid = min(bid, DAILY_SALARY * 0.26)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * 1.2
    if budget < reserve_floor:
        bid = min(bid, max(0.0, budget * 0.55))

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Gather yesterday bids from alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents alive, bid minimally but still plausible
    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate how aggressive the field was yesterday
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        min_prev_bid = min(yesterday_bids)
        # Cindy-like behavior: high bid around 120-150 in trace; we shade slightly below max
        # Use my HP to decide whether to contest harder.
        hp = float(my_status.get('hp', 0.0))
        budget = float(my_status.get('budget', 0.0))

        # Supply pressure heuristic: with higher supply, we can bid less; with lower supply, bid more.
        # Map supply in [15,25] to pressure in [1.1,0.9]
        if MAX_SUPPLY != MIN_SUPPLY:
            pressure = 1.1 - 0.2 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
        else:
            pressure = 1.0

        # Base competitive target: slightly below yesterday max to avoid overpaying,
        # but enough to beat the runner-up if they were near max.
        # If my HP is critical, increase to near max.
        if hp <= 2:
            target = max_prev_bid * 0.98
        elif hp <= 4:
            target = max_prev_bid * 0.93
        else:
            target = max_prev_bid * 0.88

        # Also ensure not too low relative to yesterday's minimum
        floor_target = max(DAILY_SALARY * 0.55, min_prev_bid + 2.0)
        target = max(target, floor_target)

        # Apply pressure shading
        target = target * pressure

        # Cap bids to budget and avoid exceeding typical salary-scale too much
        # (game likely has bid caps; keep within 1.8*DAILY_SALARY)
        cap = 1.8 * DAILY_SALARY
        bid = min(budget, cap, target)

        # If budget is extremely low, still bid at least a small fraction to prevent immediate death
        if bid <= 0.0:
            bid = min(budget, DAILY_SALARY * 0.2)

        return float(max(0.0, bid))

    # If no yesterday bids available, use HP + supply heuristic
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    if supply <= float(WATER_REQ):
        base = DAILY_SALARY * 0.85
    else:
        base = DAILY_SALARY * 0.6

    if hp <= 2:
        base = DAILY_SALARY * 0.95
    elif hp <= 4:
        base = DAILY_SALARY * 0.75

    bid = min(budget, base)
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 80

    if my_status['hp'] < 4:
        return min(my_status['budget'], avg_prev_bid * 1.1)

    if supply < 18:
        return min(my_status['budget'], avg_prev_bid * 1.05)

    return min(my_status['budget'], avg_prev_bid * 0.85)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    # collect maximum previous bid from alive opponents
    max_prev_bid = 0
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bid = prev['bid']
                if prev_bid > max_prev_bid:
                    max_prev_bid = prev_bid

    # base decision on health and desperation
    if my_status['no_water_days'] > 0:
        # desperate: bid high to get water
        bid = min(my_status['budget'], DAILY_SALARY * 0.9)
    elif my_status['hp'] > 5:
        # healthy, try to save money
        bid = min(my_status['budget'], 30)
    else:
        # moderate health, compete
        bid = min(my_status['budget'], max(40, max_prev_bid + 1))

    # ensure bid is non-negative
    bid = max(0, bid)
    return bid
